-- v3 (D-13) K3 replay, Adobe ARP FF K8 (BBCC314C-...), sessions created 2026-11-18 00:00-07:00 UTC, no sampling. Identical to v2
-- 13_replay_K3_adobe_v2.sql (cohort USER_IP LIKE '2a03:4000:6:cc79:%', List A/B/C, LT rule) with one ST/LT pair per variant from
-- 02_build_matrices_v3.py adobe (base sampled by window, 04_k3_adobe_key_base_sampled_p999.sql). Output: v|cohort|d|grp|n|thr ST|T|NA n/High%|stc p10/p50/max
WITH g(k,d,grp,st0,lt0,st1,lt1,st2,lt2,st3,lt3) AS (SELECT * FROM VALUES ('BBCC314C',-1,'Desktop',90,5400,90,5400,90,5400,90,5400),('BBCC314C',-1,'Mobile',90,5400,90,5400,90,5400,90,5400),('BBCC314C',-1,'Linux',90,5400,90,5400,90,5400,90,5400),('BBCC314C',-1,'WinRDVM',90,5400,90,5400,90,5400,90,5400),('BBCC314C',-1,'Other',90,5400,90,5400,90,5400,90,5400),('BBCC314C',1,'Desktop',90,5400,90,5400,90,5400,90,5400),('BBCC314C',1,'Mobile',90,5400,90,5400,90,5400,90,5400),('BBCC314C',1,'Linux',90,5400,90,5400,90,5400,90,5400),('BBCC314C',1,'WinRDVM',90,5400,90,5400,90,5400,90,5400),('BBCC314C',1,'Other',90,5400,90,5400,90,5400,90,5400),('BBCC314C',3,'Desktop',198.0,11880.0,198.0,11880.0,352.0,21120.0,352.0,21120.0),('BBCC314C',3,'Mobile',20.0,1200.0,20.0,1200.0,62.3,3738.0,62.3,3738.0),('BBCC314C',3,'Linux',90,5400,90,5400,90,5400,90,5400),('BBCC314C',3,'WinRDVM',90,5400,90,5400,90,5400,90,5400),('BBCC314C',3,'Other',90,5400,90,5400,90,5400,90,5400),('BBCC314C',7,'Desktop',51.0,4080.0,51.0,4080.0,258.0,20640.0,258.0,20640.0),('BBCC314C',7,'Mobile',7.5,600.0,7.5,600.0,9.0,720.0,9.0,720.0),('BBCC314C',7,'Linux',9.0,720.0,9.0,720.0,16.35,1308.0,16.35,1308.0),('BBCC314C',7,'WinRDVM',15.0,1200.0,15.0,1200.0,43.5,3480.0,43.5,3480.0),('BBCC314C',7,'Other',51.0,4080.0,51.0,4080.0,90,5400,90,5400),('BBCC314C',15,'Desktop',14.0,1680.0,14.0,1680.0,24.0,2880.0,24.0,2880.0),('BBCC314C',15,'Mobile',32.0,3840.0,32.0,3840.0,76.0,9120.0,76.0,9120.0),('BBCC314C',15,'Linux',12.0,1440.0,12.0,1440.0,16.8,2016.0,16.8,2016.0),('BBCC314C',15,'WinRDVM',7.95,636.0,7.95,636.0,18.3,1464.0,18.3,1464.0),('BBCC314C',15,'Other',20.0,2400.0,20.0,2400.0,46.0,5400,46.0,5400),('BBCC314C',31,'Desktop',22.0,2640.0,22.0,2640.0,52.0,6240.0,52.0,6240.0),('BBCC314C',31,'Mobile',24.0,2880.0,24.0,2880.0,85.2,10224.0,85.2,10224.0),('BBCC314C',31,'Linux',20.0,2400.0,20.0,2400.0,118.4,14208.0,118.4,14208.0),('BBCC314C',31,'WinRDVM',10.5,840.0,10.5,840.0,15.0,1200.0,15.0,1200.0),('BBCC314C',31,'Other',22.0,2640.0,22.0,2640.0,56.0,5400,56.0,5400),('BBCC314C',63,'Desktop',34.0,6120.0,34.0,6120.0,104.0,18720.0,104.0,18720.0),('BBCC314C',63,'Mobile',54.0,9720.0,54.0,9720.0,164.4,29592.0,164.4,29592.0),('BBCC314C',63,'Linux',14.0,2520.0,14.0,2520.0,22.0,3960.0,22.0,3960.0),('BBCC314C',63,'WinRDVM',25.5,2040.0,25.5,2040.0,52.8,4224.0,52.8,4224.0),('BBCC314C',63,'Other',36.0,5400,36.0,5400,90,5400,90,5400)),
s0 AS (SELECT di_dictionary_num_matched_at_session_created d, os_at_session_created os, COALESCE(webgl_unmasked_renderer_at_session_created,'') r, COALESCE(cdn__ja4_hash_at_session_created,'') ja4, COALESCE(ua_at_session_created,'') ua, COALESCE(user_ip_at_session_created,'') ip, IFF(latest_risk_band='High',1,0) hi, di_short_term_count_at_session_created stc, di_long_term_count_at_session_created ltc, IFF(di_short_term_threshold_breached_at_session_created,1,0) stb FROM ARK_PROD.STARFLEET.PROD_INT_SESSION_SUMMARY WHERE public_key='BBCC314C-4937-4CCD-B0A3-FDF0F0F7603C' AND session_last_timestamp>='2026-11-18 00:00' AND session_last_timestamp<'2026-11-18 13:00' AND session_ts>='2026-11-18 00:00' AND session_ts<'2026-11-18 07:00' AND di_dictionary_num_matched_at_session_created IS NOT NULL),
s1 AS (SELECT s0.*, CASE WHEN r ILIKE '%SwiftShader%' OR r ILIKE '%llvmpipe%' OR r ILIKE '%VirtualBox%' OR r ILIKE '%VMware%' THEN 'A' WHEN r ILIKE '%Basic Render Driver%' AND COALESCE(os,'')<>'Windows' THEN 'B' WHEN COALESCE(os,'') IN ('','--') AND r<>'' THEN 'B' WHEN ja4 LIKE 't%' AND SPLIT_PART(ja4,'_',2) IN ('a09f3c656075','2802a3db6c62') AND os IN ('Windows','GNU/Linux','Ubuntu','Chrome OS') THEN 'C' WHEN ua LIKE '%Chrome/%' AND RIGHT(SPLIT_PART(ja4,'_',1),2)='h1' THEN 'C' WHEN TRY_TO_NUMBER(REGEXP_SUBSTR(ua,'Chrome/([0-9]+)',1,1,'e',1))>=70 AND ja4 LIKE 't12%' THEN 'C' END AS x, CASE WHEN r ILIKE '%Basic Render Driver%' AND os='Windows' THEN 'WinRDVM' WHEN os IN ('Windows','OS X','Chrome OS') THEN 'Desktop' WHEN os IN ('iOS','iPadOS','Android') THEN 'Mobile' WHEN os IN ('GNU/Linux','Ubuntu') THEN 'Linux' ELSE 'Other' END AS grp, IFF(ip LIKE '2a03:4000:6:cc79:%','attack','rest') c FROM s0),
f AS (SELECT s1.*, v.column1 v, CASE v.column1 WHEN 0 THEN st0 WHEN 1 THEN st1 WHEN 2 THEN st2 ELSE st3 END st, CASE v.column1 WHEN 0 THEN lt0 WHEN 1 THEN lt1 WHEN 2 THEN lt2 ELSE lt3 END lt FROM s1 LEFT JOIN g ON g.d=s1.d AND g.grp=s1.grp CROSS JOIN (SELECT column1 FROM VALUES (0),(1),(2),(3)) v),
h AS (SELECT f.*, IFF(x IS NULL AND (stc>st OR ltc>lt),1,0) na FROM f)
SELECT v||'|'||c||'|'||COALESCE(d::STRING,'ALL')||'|'||COALESCE(IFF(x IS NULL,grp,'SKIP_'||x),'ALL')||'|n='||COUNT(*)||'|hi='||ROUND(100*AVG(hi),1)||'|thr='||COALESCE(MAX(st)::STRING,'-')||'|T='||SUM(stb)||'|NA='||SUM(na)||'/'||COALESCE(ROUND(100*SUM(na*hi)/NULLIF(SUM(na),0),1)::STRING,'-')||'|stc='||PERCENTILE_DISC(0.1) WITHIN GROUP (ORDER BY stc)||'/'||MEDIAN(stc)||'/'||MAX(stc) r
FROM h GROUP BY GROUPING SETS ((v,c,d,x,grp),(v,c)) HAVING (c='attack' AND COUNT(*)>=20) OR d IS NULL ORDER BY 1;
